    // ─────────── فصل ۱: بیداری ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Awakening", titlePersian = "بیداری",
        paragraphs = listOf(
            StoryParagraph("One morning, when Gregor Samsa woke from troubled dreams, he found himself transformed in his bed into a monstrous vermin.", "یک صبح، هنگامی که گرگور سامسا از رؤیاهای آشفته بیدار شد، خود را در تختش به حشره‌ای هیولایی تبدیل‌یافته یافت."),
            StoryParagraph("He was lying on his hard, as it were armor-plated, back, and when he lifted his head a little, he could see his dome-like brown belly divided into stiff arched segments.", "روی پشت سخت و زره‌مانندش دراز کشیده بود و وقتی کمی سرش را بلند کرد، شکم قهوه‌ای گنبدمانندش را دید که به بخش‌های قوسی سخت تقسیم شده بود."),
            StoryParagraph("His numerous legs, which were pitifully thin compared to the rest of his bulk, waved helplessly before his eyes.", "پاهای متعددش، که در مقایسه با بقیه جثه‌اش به‌طرز رقت‌انگیزی نازک بودند، درمانده جلوی چشمانش موج می‌زدند."),
            StoryParagraph("'What has happened to me?' he thought. It was no dream.", "فکر کرد: «چه بر سرم آمده؟» خواب نبود."),
            StoryParagraph("His room, a proper human room although a little too small, lay peacefully between its four familiar walls.", "اتاقش، اتاقی انسانی و مناسب هرچند کمی کوچک، آرام بین چهار دیوار آشنایش دراز کشیده بود."),
            StoryParagraph("A collection of textile samples lay spread out on the table — Samsa was a travelling salesman — and above it there hung a picture that he had recently cut out of an illustrated magazine.", "مجموعه‌ای از نمونه‌های پارچه روی میز پهن شده بود — سامسا فروشنده دوره‌گرد بود — و بالای آن تصویری آویزان بود که اخیراً از مجله‌ای مصور بریده بود."),
            StoryParagraph("It showed a lady fitted out with a fur hat and fur boa who sat upright, raising a heavy fur muff that covered the whole of her lower arm towards the viewer.", "تصویری از بانویی را نشان می‌داد با کلاه و شال خز که راست نشسته و ماف خزی سنگینی را که تمام بازوی پایینی‌اش را می‌پوشاند به سمت بیننده بالا آورده بود."),
            StoryParagraph("Gregor then turned to look out the window at the dull weather, and the sight of the rain falling in torrents made him feel melancholy.", "گرگور سپس به سمت پنجره چرخید تا هوای دلگیر بیرون را نگاه کند و دیدن بارانی که سیل‌آسا می‌بارید او را غمگین کرد."),
            StoryParagraph("'How about going back to sleep for a few hours and forgetting about this nonsense?' he thought, but he could not carry it out.", "فکر کرد: «چطور است چند ساعت دیگر بخوابم و این مزخرف را فراموش کنم؟» اما نمی‌توانست انجامش دهد."),
            StoryParagraph("He was accustomed to sleeping on his right side, and in his present state he could not get into that position.", "به خوابیدن روی پهلوی راست عادت داشت و در وضعیت فعلی نمی‌توانست به آن حالت برسد."),
            StoryParagraph("No matter how hard he threw himself onto his right side, he always rolled onto his back again.", "هر چقدر سخت تلاش می‌کرد خودش را روی پهلوی راست بیندازد، همیشه دوباره روی پشتش می‌غلتید."),
            StoryParagraph("He must have tried it a hundred times, shutting his eyes so as not to see his wriggling legs, and only gave up when he began to feel a slight, dull pain in his side.", "باید صد بار امتحان کرده باشد، چشمانش را می‌بست تا پاهای لول‌خورنده‌اش را نبیند و فقط وقتی دست کشید که شروع کرد به حس دردی خفیف و کدر در پهلویش."),
            StoryParagraph("'Oh, God,' he thought, 'what a demanding job I've chosen! Day in, day out on the road.'", "فکر کرد: «آه، خدای من، چه شغل طاقت‌فرسایی انتخاب کرده‌ام! روز از پی روز در راه.»"),
            StoryParagraph("The stresses of the job were far greater than those of the actual work in the office, and on top of that there was the misery of traveling.", "فشارهای شغل خیلی بیشتر از خود کار در دفتر بود و روی آن بدبختی سفر هم بود."),
            StoryParagraph("There were the worries about train connections, the bad and irregular meals, the constant stream of casual acquaintances who never became friends.", "نگرانی‌ها درباره اتصالات قطار، غذاهای بد و نامنظم، جریان مداوم آشنایان اتفاقی که هرگز دوست نمی‌شدند."),
            StoryParagraph("'To hell with it all!' he thought, and he tried to move his legs once more, but they were completely out of control.", "فکر کرد: «به جهنم همه‌اش!» و یک بار دیگر تلاش کرد پاهایش را حرکت دهد، اما کاملاً از کنترل خارج بودند."),
            StoryParagraph("He looked over at the alarm clock, which was ticking on the chest of drawers, and it was already half past six.", "به ساعت زنگ‌دار نگاه کرد که روی دراور تیک‌تاک می‌کرد و از قبل شش و نیم بود."),
            StoryParagraph("The next train left at seven, and he would have to run to catch it, and even then he would probably be late.", "قطار بعدی ساعت هفت حرکت می‌کرد و باید می‌دوید تا به آن برسد و حتی آن وقت هم احتمالاً دیر می‌رسید."),
            StoryParagraph("But then he remembered that he could not possibly catch a train in his present condition.", "اما بعد به یاد آورد که به هیچ وجه نمی‌تواند در وضعیت فعلی‌اش به قطاری برسد."),
            StoryParagraph("His first thought, when he found himself in this impossible situation, was not to wonder what had happened to him, but to think about how he could continue to support his family.", "اولین فکرش وقتی خودش را در این وضعیت غیرممکن یافت، نه این بود که بپرسد چه بر سرش آمده، بلکه فکر کردن به اینکه چطور می‌تواند به حمایت از خانواده‌اش ادامه دهد."),
            StoryParagraph("His father had lost his business five years earlier, and since then, Gregor had been the sole provider for the family.", "پدرش پنج سال پیش تجارتش را از دست داده بود و از آن زمان، گرگور تنها نان‌آور خانواده بود."),
            StoryParagraph("His mother was sick with asthma, his sister Grete was only seventeen and needed to be sent to a conservatory to study the violin.", "مادرش از آسم رنج می‌برد، خواهرش گرته فقط هفده ساله بود و باید به کنسرواتوار فرستاده می‌شد تا ویولن بیاموزد."),
            StoryParagraph("And the family had debts that had to be paid, debts that Gregor had been slowly paying off from his earnings.", "خانواده بدهی‌هایی داشت که باید پرداخت می‌شد، بدهی‌هایی که گرگور آهسته از درآمدش پرداخت می‌کرد."),
            StoryParagraph("'If I lose my job,' he thought, 'my family will be ruined.' And this thought, even more than the horror of his transformation, filled him with despair.", "فکر کرد: «اگر شغلم را از دست بدهم، خانواده‌ام نابود می‌شود.» و این فکر، حتی بیشتر از وحشت دگردیسی‌اش، او را پر از ناامیدی کرد."),
            StoryParagraph("He tried to get out of bed, and after much difficulty, he managed to rock himself back and forth until he finally rolled off the bed onto the floor, landing with a dull thud.", "تلاش کرد از تخت بیرون بیاید و بعد از دشواری زیاد، موفق شد خودش را جلو و عقب تکان دهد تا بالاخره از تخت روی زمین افتاد و با صدایی کدر فرود آمد."),
            StoryParagraph("The fall had not hurt him much, because his body was now strangely hard and armored, but the noise it made was loud enough to be heard in the next room.", "افتادن زیاد آزارش نداد، چون بدنش حالا به‌طرز عجیبی سخت و زره‌پوش بود، اما صدایی که ایجاد کرد آنقدر بلند بود که در اتاق بعدی شنیده شود."),
            StoryParagraph("'Something must have fallen in Gregor's room,' said his mother from the next room, and Gregor heard his father and sister come to investigate.", "مادرش از اتاق بعدی گفت: «حتماً چیزی در اتاق گرگور افتاده،» و گرگور شنید که پدر و خواهرش برای بررسی می‌آیند."),
            StoryParagraph("The door to his room was locked from the inside, as it always was at night, and there was no way for anyone to enter without his consent.", "در اتاقش از داخل قفل بود، همان‌طور که همیشه شب‌ها بود و راهی برای کسی نبود که بدون رضایتش وارد شود."),
            StoryParagraph("'Gregor, are you all right?' his mother called through the door, and her voice was full of anxiety.", "مادرش از پشت در صدا زد: «گرگور، حالت خوب است؟» و صدایش پر از اضطراب بود."),
            StoryParagraph("Gregor tried to answer, but the sound that came from his throat was not a human voice; it was a strange, animal-like squeaking that he could not control.", "گرگور تلاش کرد جواب دهد، اما صدایی که از گلویش آمد صدای انسانی نبود؛ جیرجیر عجیب و حیوان‌مانندی بود که نمی‌توانست کنترلش کند."),
            StoryParagraph("'Gregor?' his sister called, 'are you ill? Do you need anything?'", "خواهرش صدا زد: «گرگور؟ مریضی؟ چیزی نیاز داری؟»"),
            StoryParagraph("He managed to say 'Yes' in a voice that was almost human, and he heard his family sigh with relief on the other side of the door.", "او موفق شد «بله» بگوید با صدایی که تقریباً انسانی بود و شنید که خانواده‌اش از آن طرف در از آسودگی آه کشیدند."),
            StoryParagraph("'He is awake,' they said to each other. 'Now we can tell him about the visitor from the firm.'", "به هم گفتند: «بیدار است. حالا می‌توانیم درباره بازدیدکننده از شرکت به او بگوییم.»"),
            StoryParagraph("A short time later, there was a knock at the front door, and the family fell silent.", "کمی بعد، ضربه‌ای به در ورودی خورد و خانواده ساکت شدند."),
            StoryParagraph("It was the chief clerk from the firm, come to find out why Gregor had not shown up for work.", "کارمند ارشد شرکت بود، آمده بود بفهمد چرا گرگور سر کار نیامده است."),
            StoryParagraph("'Mr. Samsa,' the clerk called through the door, 'the manager has sent me to inquire why you are not at work.'", "کارمند از پشت در صدا زد: «آقای سامسا، مدیر مرا فرستاده تا بپرسم چرا سر کار نیستید.»"),
            StoryParagraph("Gregor, still on the floor of his room, listened to the clerk's voice and felt a wave of terror wash over him.", "گرگور که هنوز روی کف اتاقش بود، به صدای کارمند گوش داد و موجی از وحشت او را فرا گرفت."),
            StoryParagraph("He knew that his family depended on his job, that his job depended on his showing up for work, that his showing up for work was now impossible.", "می‌دانست که خانواده‌اش به شغلش وابسته است، شغلش به حاضر شدنش در محل کار وابسته است و حاضر شدنش در محل کار حالا غیرممکن بود.")
        )
    )

    // ─────────── فصل ۲: شوک خانواده ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Family's Shock", titlePersian = "شوک خانواده",
        paragraphs = listOf(
            StoryParagraph("'Just a moment,' Gregor called out, in a voice that was almost his own, 'I will be ready in a moment.'", "گرگور صدا زد: «یک لحظه،» با صدایی که تقریباً صدای خودش بود، «یک لحظه دیگر آماده می‌شوم.»"),
            StoryParagraph("He began to struggle desperately to get himself upright, to open the door, to show them all that everything was fine, but his body would not obey him.", "شروع کرد به تقلای ناامیدانه برای ایستادن، باز کردن در، نشان دادن به همه که همه چیز خوب است، اما بدنش اطاعتش نمی‌کرد."),
            StoryParagraph("'Open the door, Mr. Samsa,' the clerk called again, 'or I shall have to report you to the manager.'", "کارمند دوباره صدا زد: «در را باز کن، آقای سامسا، یا مجبور می‌شوم به مدیر گزارش دهم.»"),
            StoryParagraph("The family, in the next room, began to plead with Gregor to open the door, and their voices, full of fear and shame, only made his desperation worse.", "خانواده در اتاق بعدی شروع کردند به التماس کردن از گرگور که در را باز کند و صدایشان، پر از ترس و شرم، فقط ناامیدی‌اش را بدتر کرد."),
            StoryParagraph("Finally, with a supreme effort, he managed to grip the key in his mandibles and turn it in the lock, and the door slowly swung open.", "بالاخره، با تلاشی فوق‌العاده، موفق شد کلید را در آرواره‌هایش بگیرد و در قفل بچرخاند و در آهسته باز شد."),
            StoryParagraph("The clerk, standing in the doorway, took one look at the creature on the floor and let out a shriek of horror.", "کارمند که در چارچوب در ایستاده بود، یک نگاه به موجود روی زمین انداخت و فریاد وحشتی کشید."),
            StoryParagraph("Gregor's mother fainted, his sister burst into tears, his father grabbed a walking stick and began to wave it threateningly.", "مادر گرگور غش کرد، خواهرش به گریه افتاد، پدرش عصایی چنگ کرد و شروع کرد به تهدیدآمیز تکان دادنش."),
            StoryParagraph("'Gregor!' his sister cried. 'What has happened to you? Why have you done this?'", "خواهرش گریه کرد: «گرگور! چه بر سرت آمده؟ چرا این کار را کردی؟»"),
            StoryParagraph("Gregor tried to speak, tried to explain, tried to reassure them, but the sounds that came from his throat only made them more terrified.", "گرگور تلاش کرد صحبت کند، تلاش کرد توضیح دهد، تلاش کرد به آن‌ها اطمینان دهد، اما صداهایی که از گلویش می‌آمد فقط بیشتر وحشتزده‌شان می‌کرد."),
            StoryParagraph("He retreated back into his room, and the door was slammed shut and locked from the outside.", "او به اتاقش عقب‌نشینی کرد و در محکم بسته شد و از بیرون قفل شد."),
            StoryParagraph("The family gathered in the living room, and through the wall, Gregor could hear them talking about him in whispers.", "خانواده در نشیمن جمع شدند و از پشت دیوار، گرگور می‌توانست بشنود که با زمزمه درباره‌اش صحبت می‌کنند."),
            StoryParagraph("They did not know what to do; they did not know how to explain what had happened; they did not know how to proceed.", "نمی‌دانستند چه کنند؛ نمی‌دانستند چطور توضیح دهند چه اتفاقی افتاده؛ نمی‌دانستند چطور ادامه دهند."),
            StoryParagraph("The clerk had fled the house in terror, and the family knew that he would tell everyone at the firm what he had seen.", "کارمند وحشت‌زده از خانه فرار کرده بود و خانواده می‌دانستند که به همه در شرکت خواهد گفت چه دیده است."),
            StoryParagraph("Gregor's position at the firm was lost; his career was over; his life as a human being was over.", "موقعیت گرگور در شرکت از دست رفته بود؛ حرفه‌اش تمام شده بود؛ زندگی‌اش به‌عنوان یک انسان تمام شده بود."),
            StoryParagraph("And yet, in his mind, he was still Gregor; he still thought like a human being; he still felt like a human being.", "و با این حال، در ذهنش، هنوز گرگور بود؛ هنوز مثل یک انسان فکر می‌کرد؛ هنوز مثل یک انسان حس می‌کرد."),
            StoryParagraph("He still remembered his mother's voice, his sister's laughter, his father's stern face; he still remembered the dreams he had had, the plans he had made, the life he had wanted.", "هنوز صدای مادرش را به یاد می‌آورد، خنده خواهرش، چهره جدی پدرش؛ هنوز رؤیاهایی که دیده بود را به یاد می‌آورد، نقشه‌هایی که کشیده بود، زندگی‌ای که خواسته بود."),
            StoryParagraph("But none of that mattered now; what mattered was that he was trapped in a body that was not his, that could not do the things that human bodies do, that could not speak, could not walk upright, could not open doors.", "اما هیچ‌کدام حالا اهمیت نداشت؛ آنچه اهمیت داشت این بود که در بدنی گرفتار بود که مال خودش نبود، نمی‌توانست کارهایی که بدن‌های انسانی می‌کنند را بکند، نمی‌توانست صحبت کند، نمی‌توانست راست راه برود، نمی‌توانست درها را باز کند."),
            StoryParagraph("He spent the first day alone in his room, hungry and frightened, listening to the sounds of the family in the next room.", "اولین روز را تنهای تنها در اتاقش گذراند، گرسنه و ترسیده، به صداهای خانواده در اتاق بعدی گوش می‌داد."),
            StoryParagraph("He heard them weeping; he heard them arguing; he heard them sitting in silence, unable to speak to each other.", "شنید که گریه می‌کنند؛ شنید که بحث می‌کنند؛ شنید که در سکوت می‌نشینند، ناتوان از صحبت کردن با هم."),
            StoryParagraph("And he heard, most painful of all, the sound of his sister's sobs, because Grete had always been closest to him, and her grief was the hardest to bear.", "و شنید، دردناک‌ترین از همه، صدای هق‌هق خواهرش را، چون گرته همیشه نزدیک‌ترین به او بود و اندوهش سخت‌ترین برای تحمل بود."),
            StoryParagraph("The next morning, Grete came to his door with a bowl of milk and some bread, and she placed them on the floor just inside the room.", "صبح روز بعد، گرته با کاسه‌ای شیر و کمی نان به در اتاقش آمد و آن‌ها را روی زمین درست داخل اتاق گذاشت."),
            StoryParagraph("'Gregor,' she called softly, 'I have brought you something to eat.'", "آرام صدا زد: «گرگور، چیزی برای خوردن آورده‌ام.»"),
            StoryParagraph("Gregor waited until she had gone, and then he crawled over to the bowl, and he tried to drink the milk, but the taste was strange to him now.", "گرگور منتظر ماند تا رفت و بعد به سمت کاسه خزید و تلاش کرد شیر را بنوشد، اما طعمش حالا برایش عجیب بود."),
            StoryParagraph("He could not drink it; his body rejected it; his new body craved different things.", "نمی‌توانست بنوشدش؛ بدنش ردش می‌کرد؛ بدن جدیدش چیزهای دیگری می‌خواست."),
            StoryParagraph("When Grete returned and saw that the milk was untouched, she was both hurt and puzzled, and she did not know what to do.", "وقتی گرته برگشت و دید شیر دست‌نخورده است، هم زخمی شد و هم متعجب و نمی‌دانست چه کند."),
            StoryParagraph("She tried other foods: cheese, vegetables, leftovers that had been thrown out, and Gregor ate them all eagerly, preferring the old and rotting to the fresh.", "غذاهای دیگری امتحان کرد: پنیر، سبزیجات، باقی‌مانده‌هایی که دور انداخته شده بودند و گرگور همه را با اشتیاق خورد، کهنه و پوسیده را به تازه ترجیح می‌داد."),
            StoryParagraph("This discovery made Grete both relieved and disgusted, but she did not speak of it to her parents, because she did not want to add to their suffering.", "این کشف هم آسوده‌اش کرد و هم منزجرش کرد، اما به والدینش چیزی نگفت، چون نمی‌خواست به رنجشان بیفزاید."),
            StoryParagraph("From that day forward, Grete became his caretaker; she brought him food every day, cleaned his room, tried to make his existence bearable.", "از آن روز به بعد، گرته مراقبش شد؛ هر روز برایش غذا می‌آورد، اتاقش را تمیز می‌کرد، تلاش می‌کرد وجودش را تحمل‌پذیر کند."),
            StoryParagraph("She was the only one who could enter his room, the only one who could bear to look at him, the only one who still seemed to think of him as her brother.", "او تنها کسی بود که می‌توانست وارد اتاقش شود، تنها کسی که می‌توانست تحمل کند نگاهش کند، تنها کسی که هنوز به نظر می‌رسید او را به‌عنوان برادرش می‌بیند."),
            StoryParagraph("His parents could not bear to see him, and they avoided his room entirely, speaking of him in whispers, as though he had already died.", "والدینش نمی‌توانستند تحمل کنند ببینندش و کاملاً از اتاقش دوری می‌کردند و با زمزمه درباره‌اش صحبت می‌کردند، گویی از قبل مرده است."),
            StoryParagraph("They had lost not only a son, but also the only source of income for the family, and the economic consequences of Gregor's transformation were immediate and severe.", "آن‌ها نه تنها پسری را از دست داده بودند، بلکه تنها منبع درآمد خانواده را هم از دست داده بودند و پیامدهای اقتصادی دگردیسی گرگور فوری و شدید بودند."),
            StoryParagraph("The family had savings, but they were not enough to live on for long, and the father, who had been retired for years, was too old and weak to find work.", "خانواده پس‌انداز داشتند، اما برای زندگی طولانی کافی نبود و پدر که سال‌ها بازنشسته بود، برای یافتن کار خیلی پیر و ضعیف بود."),
            StoryParagraph("The mother, though sick, began to take in sewing, and the sister, who had hoped to study music, took a job as a salesgirl in a shop.", "مادر، هرچند مریض، شروع کرد به خیاطی و خواهر، که امید داشت موسیقی بخواند، شغلی به‌عنوان فروشنده در مغازه‌ای گرفت."),
            StoryParagraph("And so the family began its long decline, slowly, painfully, one small step at a time, while Gregor, helpless in his room, could do nothing but watch.", "و اینگونه خانواده افول طولانی‌اش را آغاز کرد، آهسته، دردناک، یک قدم کوچک در یک زمان، در حالی که گرگور درمانده در اتاقش، نمی‌توانست کاری بکند جز تماشا.")
        )
    )

    // ─────────── فصل ۳: انزوا ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Isolation", titlePersian = "انزوا",
        paragraphs = listOf(
            StoryParagraph("Days passed, and then weeks, and Gregor's existence settled into a routine of hunger, loneliness, and slow physical decline.", "روزها گذشتند و سپس هفته‌ها و وجود گرگور به روالی از گرسنگی، تنهایی و زوال جسمی آهسته تبدیل شد."),
            StoryParagraph("He spent most of his time hiding under the sofa, because the darkness comforted him, and because his family could not bear to see him.", "او بیشتر وقتش را زیر مبل پنهان می‌کرد، چون تاریکی آرامش می‌دادش و چون خانواده‌اش نمی‌توانستند تحمل کنند ببینندش."),
            StoryParagraph("He would crawl out at night, when everyone was asleep, and he would wander around his room, feeling the walls with his antennae.", "شب‌ها بیرون می‌خزید، وقتی همه خواب بودند و در اتاقش پرسه می‌زد، دیوارها را با شاخک‌هایش حس می‌کرد."),
            StoryParagraph("He remembered what it had been like to walk upright, to open doors, to speak; he remembered everything he had lost.", "به یاد می‌آورد ایستاده راه رفتن، باز کردن درها، صحبت کردن چه حسی داشت؛ هر چیزی که از دست داده بود را به یاد می‌آورد."),
            StoryParagraph("He thought about his family, about the sacrifices they were making for him, about the burden he had become.", "به خانواده‌اش فکر می‌کرد، به فداکاری‌هایی که برایش می‌کردند، به باری که شده بود."),
            StoryParagraph("And he wished, more than anything, that he could speak to them, that he could explain, that he could apologize.", "و بیشتر از هر چیزی آرزو می‌کرد می‌توانست با آن‌ها صحبت کند، توضیح دهد، عذرخواهی کند."),
            StoryParagraph("But his voice was gone, and with it, his ability to communicate, to connect, to be understood.", "اما صدایش رفته بود و با آن، توانایی‌اش برای ارتباط برقرار کردن، وصل شدن، فهمیده شدن."),
            StoryParagraph("The isolation that followed was more painful than any physical suffering, because human beings are made for connection, and a human being without connection is not truly alive.", "انزوایی که در پی آمد از هر رنج جسمی دردناک‌تر بود، چون انسان‌ها برای ارتباط ساخته شده‌اند و انسانی بدون ارتباط واقعاً زنده نیست."),
            StoryParagraph("One day, his sister noticed that he had not eaten for several days, and she brought him some fresh food, hoping to tempt his appetite.", "یک روز، خواهرش متوجه شد چند روز است نخورده و کمی غذای تازه برایش آورد، به امید آنکه اشتهایش را تحریک کند."),
            StoryParagraph("But Gregor could not eat, not because he was not hungry, but because the food reminded him of everything he had lost.", "اما گرگور نمی‌توانست بخورد، نه چون گرسنه نبود، بلکه چون غذا او را به یاد هر چیزی که از دست داده بود می‌انداخت."),
            StoryParagraph("Eating it felt like a betrayal of his former self, of the man he had once been, of the life he had once lived.", "خوردنش مثل خیانت به خود سابقش بود، به مردی که زمانی بوده، به زندگی‌ای که زمانی داشته."),
            StoryParagraph("He pushed the food away with his leg, and his sister, misunderstanding this gesture, thought he was rejecting her kindness, and she began to cry.", "او غذا را با پایش کنار زد و خواهرش که این حرکت را اشتباه فهمید، فکر کرد لطفش را رد می‌کند و شروع کرد به گریه کردن."),
            StoryParagraph("Gregor wanted to comfort her, wanted to tell her that he was grateful, that he loved her, that she was the only one who still cared.", "گرگور می‌خواست دلداری‌اش دهد، می‌خواست به او بگوید سپاسگزار است، دوستش دارد، او تنها کسی است که هنوز اهمیت می‌دهد."),
            StoryParagraph("But he could not, and the frustration was unbearable, and he retreated under the sofa and stayed there for hours, listening to his sister's sobs.", "اما نمی‌توانست و ناکامی تحمل‌ناپذیر بود و زیر مبل عقب‌نشینی کرد و ساعت‌ها آنجا ماند و به هق‌هق‌های خواهرش گوش داد."),
            StoryParagraph("The gap between him and his family grew wider with every passing day, and the love that had once bound them together began to erode.", "فاصله میان او و خانواده‌اش با هر روزی که می‌گذشت پهن‌تر می‌شد و عشقی که زمانی آن‌ها را به هم بسته بود شروع به فرسایش کرد."),
            StoryParagraph("It was replaced by disgust, by fear, by resentment, by all the emotions that human beings feel when confronted with something they cannot understand.", "جایگزینش شد انزجار، ترس، کینه، تمام احساساتی که انسان‌ها وقتی با چیزی که نمی‌فهمند روبرو می‌شوند حس می‌کنند."),
            StoryParagraph("Gregor understood this, and he did not blame them, because he knew that he had become something that could not be loved, something that could only be tolerated.", "گرگور این را می‌فهمید و سرزنششان نمی‌کرد، چون می‌دانست به چیزی تبدیل شده که نمی‌توانست دوست داشته شود، چیزی که فقط می‌توانست تحمل شود."),
            StoryParagraph("But understanding did not make the pain any less, and each night, as he lay in the darkness beneath the sofa, he wept, though no tears came from his insect eyes.", "اما فهمیدن درد را کمتر نمی‌کرد و هر شب، همان‌طور که در تاریکی زیر مبل دراز می‌کشید، گریه می‌کرد، هرچند اشکی از چشمان حشره‌ای‌اش نمی‌آمد."),
            StoryParagraph("He wept for the life he had lost, for the family he could no longer help, for the man he had once been, and for the creature he had become.", "او برای زندگی‌ای که از دست داده بود گریه می‌کرد، برای خانواده‌ای که دیگر نمی‌توانست کمکشان کند، برای مردی که زمانی بوده و برای موجودی که شده بود."),
            StoryParagraph("And he wept, most of all, for the simple, irreplaceable fact of being human, a fact that he had never appreciated until it was taken from him forever.", "و بیشتر از همه، برای واقعیت ساده و جبران‌ناپذیر انسان بودن گریه می‌کرد، واقعیتی که هرگز قدرش را ندانسته بود تا وقتی برای همیشه از او گرفته شد."),
            StoryParagraph("One evening, his sister came to his room and found him looking at the picture of the lady in furs, the picture he had cut out of a magazine years ago.", "یک عصر، خواهرش به اتاقش آمد و او را دید که به تصویر بانوی خزپوش نگاه می‌کند، تصویری که سال‌ها پیش از مجله‌ای بریده بود."),
            StoryParagraph("She had come to move the furniture, to give him more room to crawl, and she began to take away the table and the chairs.", "او آمده بود مبلمان را جابه‌جا کند، فضای بیشتری برای خزیدنش بدهد و شروع کرد به بردن میز و صندلی‌ها."),
            StoryParagraph("But when she reached for the picture, Gregor threw himself at it, clinging to it desperately, refusing to let her take it.", "اما وقتی به سمت تصویر رفت، گرگور خود را به آن انداخت، ناامیدانه چنگش زد، امتناع کرد از گذاشتنش."),
            StoryParagraph("It was the last reminder of his human life, the last connection to the person he had been, and he could not bear to lose it.", "آخرین یادآور زندگی انسانی‌اش بود، آخرین ارتباط با شخصی که بوده و نمی‌توانست تحمل کند از دستش دهد."),
            StoryParagraph("His sister, frightened by his sudden intensity, left the picture where it was and retreated from the room, and Gregor was left alone with his small victory.", "خواهرش که از شدتش ترسیده بود، تصویر را همان‌جا گذاشت و از اتاق عقب‌نشینی کرد و گرگور با پیروزی کوچکش تنها ماند."),
            StoryParagraph("But the victory was hollow, because he knew that the picture was only a symbol, and that the reality it symbolized was gone forever.", "اما پیروزی توخالی بود، چون می‌دانست تصویر فقط نمادی بود و واقعیتی که نمادش می‌کرد برای همیشه رفته بود."),
            StoryParagraph("He crawled under the sofa and lay there in the darkness, and he thought about the past, and he thought about the future, and he thought about the present.", "زیر مبل خزید و در تاریکی دراز کشید و به گذشته فکر کرد، به آینده، به حال."),
            StoryParagraph("The past was gone; the future was unthinkable; the present was unbearable.", "گذشته رفته بود؛ آینده غیرقابل تصور بود؛ حال غیرقابل تحمل بود."),
            StoryParagraph("And yet he continued to exist; he continued to breathe; he continued to feel; he continued to suffer.", "و با این حال به وجود ادامه داد؛ به نفس کشیدن؛ به حس کردن؛ به رنج کشیدن."),
            StoryParagraph("Because that is what living beings do: they continue, even when continuing makes no sense, even when continuing is the hardest thing in the world.", "زیرا این کاری است که موجودات زنده می‌کنند: ادامه می‌دهند، حتی وقتی ادامه دادن معنایی ندارد، حتی وقتی ادامه دادن سخت‌ترین کار دنیاست."),
            StoryParagraph("And so Gregor Samsa continued, in his room, in his isolation, in his slow decline, waiting for something that might change, waiting for something that might save him.", "و اینگونه گرگور سامسا ادامه داد، در اتاقش، در انزوایش، در زوال آهسته‌اش، منتظر چیزی که ممکن بود تغییر کند، منتظر چیزی که ممکن بود نجاتش دهد."),
            StoryParagraph("But nothing came; nothing ever came; the days continued, and the weeks, and the months, and Gregor grew weaker, and weaker, and weaker.", "اما چیزی نیامد؛ هرگز چیزی نیامد؛ روزها ادامه یافتند و هفته‌ها و ماه‌ها و گرگور ضعیف‌تر و ضعیف‌تر و ضعیف‌تر شد."),
            StoryParagraph("The wound from the apple that his father had thrown at him had never healed; it had festered; it had begun to poison him from within.", "زخم سیبی که پدرش به سمتش پرت کرده بود هرگز التیام نیافته بود؛ چرک کرده بود؛ شروع کرده بود به مسموم کردنش از درون."),
            StoryParagraph("And Gregor knew, with a clarity that was almost peaceful, that he was dying, that he had been dying since the day he had woken up as an insect.", "و گرگور با وضوحی که تقریباً آرامش‌بخش بود می‌دانست که دارد می‌میرد، که از روزی که به‌عنوان حشره بیدار شده بود، داشته می‌مرده."),
            StoryParagraph("The only question was whether his death would come soon, or whether he would have to endure this existence for many more months, for many more years.", "تنها پرسش این بود که آیا مرگش به‌زودی می‌آید، یا باید این وجود را ماه‌های بیشتری تحمل کند، سال‌های بیشتری."),
            StoryParagraph("He hoped for the former; he hoped for a quick end; he hoped for the peace that only death could bring.", "امیدوار بود به اولی؛ امیدوار بود به پایانی سریع؛ امیدوار بود به آرامشی که تنها مرگ می‌توانست بیاورد.")
        )
    )

    // ─────────── فصل ۴: افول خانواده ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Family's Decline", titlePersian = "افول خانواده",
        paragraphs = listOf(
            StoryParagraph("Months passed, and the family's situation grew more desperate with each passing week.", "ماه‌ها گذشت و وضعیت خانواده با هر هفته‌ای که می‌گذشت ناامیدکننده‌تر شد."),
            StoryParagraph("The savings were almost gone, the father's health was failing, the mother's asthma was getting worse.", "پس‌انداز تقریباً تمام شده بود، سلامت پدر رو به وخامت بود، آسم مادر بدتر می‌شد."),
            StoryParagraph("The sister, who had once dreamed of studying music, now worked long hours in a shop for a meager wage.", "خواهر که زمانی رؤیای تحصیل موسیقی را داشت، حالا ساعات طولانی در مغازه‌ای برای دستمزدی اندک کار می‌کرد."),
            StoryParagraph("She was no longer the young girl who had laughed and played; she was a tired, serious woman, and Gregor could see, in her face, the marks of everything she had sacrificed.", "او دیگر دختری جوان که می‌خندید و بازی می‌کرد نبود؛ زنی خسته و جدی بود و گرگور می‌توانست، در چهره‌اش، آثار هر چیزی که فدا کرده بود را ببیند."),
            StoryParagraph("The lodgers had become the primary source of income, and the family had to be constantly careful not to offend them.", "مستأجرها به منبع اصلی درآمد تبدیل شده بودند و خانواده باید مدام مراقب می‌بود که آن‌ها را نرنجاند."),
            StoryParagraph("If the lodgers left, the family would be ruined; if the lodgers left, they would have no way to pay their debts.", "اگر مستأجرها می‌رفتند، خانواده نابود می‌شد؛ اگر مستأجرها می‌رفتند، راهی برای پرداخت بدهی‌هایشان نداشتند."),
            StoryParagraph("Gregor, listening to all this from his room, felt the weight of his uselessness pressing down upon him like a physical force.", "گرگور که همه این‌ها را از اتاقش می‌شنید، وزن بی‌فایده بودنش را مثل نیرویی جسمی روی خودش حس می‌کرد."),
            StoryParagraph("He had once been the provider, the protector, the one who made everything possible, and now he was the reason for everything that was going wrong.", "او زمانی نان‌آور، محافظ، کسی که همه چیز را ممکن می‌کرد بود و حالا دلیل هر چیزی بود که اشتباه پیش می‌رفت."),
            StoryParagraph("His sister, who had once been his closest ally, began to neglect him, bringing his food less frequently, cleaning his room less thoroughly.", "خواهرش که زمانی نزدیک‌ترین همپیمانش بود، شروع کرد به غفلت از او، غذایش را کمتر می‌آورد، اتاقش را کمتر تمیز می‌کرد."),
            StoryParagraph("She spent more and more time away from home, and when she was home, she avoided his room entirely.", "او وقت بیشتری دور از خانه می‌گذراند و وقتی در خانه بود، کاملاً از اتاقش دوری می‌کرد."),
            StoryParagraph("She had become a young woman, and she had begun to have her own life, her own friends, her own dreams.", "او زن جوانی شده بود و شروع کرده بود زندگی خودش را داشته باشد، دوستان خودش، رؤیاهای خودش."),
            StoryParagraph("And Gregor, in his insect state, could not be part of any of it; he could only watch, from a distance, as his sister's life moved forward and his own life receded.", "و گرگور در وضعیت حشره‌ای‌اش نمی‌توانست بخشی از هیچ‌کدام باشد؛ تنها می‌توانست از دور تماشا کند که زندگی خواهرش پیش می‌رود و زندگی خودش عقب می‌نشیند."),
            StoryParagraph("She still cared for him, in her own way, but the care had become a duty rather than a love.", "او هنوز به شیوه خودش اهمیت می‌داد، اما این اهمیت به وظیفه‌ای تبدیل شده بود نه عشقی."),
            StoryParagraph("She was doing what she had to do, not what she wanted to do, and Gregor could feel the difference.", "او کاری که مجبور بود می‌کرد، نه کاری که می‌خواست و گرگور می‌توانست تفاوت را حس کند."),
            StoryParagraph("His mother, who had briefly tried to visit him, had given up, because the sight of her transformed son was too much for her to bear.", "مادرش که لحظه‌ای تلاش کرده بود به دیدنش برود، دست کشیده بود، چون دیدن پسر دگردیسی‌یافته‌اش برایش بیش از حد تحمل‌پذیر بود."),
            StoryParagraph("His father, who had never been close to him, now regarded him as a monster, a curse, a punishment from God for some unknown sin.", "پدرش که هرگز به او نزدیک نبود، حالا او را مثل هیولایی می‌دید، نفرینی، مجازاتی از خدا برای گناهی ناشناخته."),
            StoryParagraph("The father had found work, finally, as a bank messenger, and he wore his uniform with a kind of pride.", "پدر بالاخره به‌عنوان پیک بانکی کار پیدا کرده بود و یونیفرمش را با نوعی افتخار می‌پوشید."),
            StoryParagraph("But the work was hard for a man of his age, and he came home exhausted every evening, and he had no patience left for anything.", "اما کار برای مردی در سن او سخت بود و هر عصر خسته به خانه می‌آمد و صبری برای چیزی نداشت."),
            StoryParagraph("One day, the father, in a fit of rage, began to throw apples at Gregor, and one of them struck him in the back and lodged there.", "یک روز، پدرش در حمله‌ای از خشم، شروع کرد به پرت کردن سیب به سمت گرگور و یکی از آن‌ها به پشتش خورد و آنجا فرو رفت."),
            StoryParagraph("Gregor fled to his room, and the apple remained embedded in his flesh, causing him terrible pain and slowly poisoning him from within.", "گرگور به اتاقش فرار کرد و سیب در گوشتش فرو رفته باقی ماند و دردی هولناک ایجاد کرد و آهسته از درون مسمومش می‌کرد."),
            StoryParagraph("No one tried to remove the apple, because no one wanted to touch him, and so it stayed there.", "هیچ‌کس تلاش نکرد سیب را بردارد، چون هیچ‌کس نمی‌خواست لمسش کند و بنابراین آنجا ماند."),
            StoryParagraph("It stayed there as a constant reminder of his father's hatred and his own helplessness; it stayed there as a kind of monument to everything that had gone wrong.", "آنجا ماند به‌عنوان یادآوری دائمی از نفرت پدرش و درماندگی خودش؛ آنجا ماند به‌عنوان نوعی یادبود برای هر چیزی که اشتباه پیش رفته بود."),
            StoryParagraph("The wound became infected, and Gregor's health, which had already been declining, began to fail rapidly.", "زخم عفونی شد و سلامت گرگور که از قبل رو به زوال بود، شروع کرد به سرعت تحلیل رفتن."),
            StoryParagraph("He stopped eating almost completely, stopped moving except when absolutely necessary.", "او تقریباً به‌طور کامل از خوردن دست کشید، از حرکت کردن دست کشید جز وقتی مطلقاً لازم بود."),
            StoryParagraph("He spent nearly all his time hidden beneath the sofa, waiting for something he could not name.", "او تقریباً تمام وقتش را زیر مبل پنهان می‌گذراند، منتظر چیزی که نمی‌توانست نامش را ببرد."),
            StoryParagraph("He was waiting for death, of course; but he did not admit this to himself, because to admit it would be to accept it.", "البته منتظر مرگ بود؛ اما این را به خودش اقرار نمی‌کرد، چون اقرار کردنش یعنی پذیرشش."),
            StoryParagraph("And so he waited, in silence, in darkness, in pain, for the end that he knew would come eventually.", "و بنابراین منتظر ماند، در سکوت، در تاریکی، در درد، برای پایانی که می‌دانست در نهایت می‌آید."),
            StoryParagraph("One day, the lodgers, who had noticed strange things about the house, gave notice that they were leaving.", "یک روز، مستأجرها که چیزهای عجیبی درباره خانه متوجه شده بودند، اعلام کردند می‌روند."),
            StoryParagraph("The family, desperate to keep them, tried to please them, tried to make their stay more comfortable, but the lodgers had already decided.", "خانواده که ناامیدانه تلاش می‌کرد نگهشان دارد، سعی کرد راضیشان کند، سعی کرد اقامتشان را راحت‌تر کند، اما مستأجرها از قبل تصمیم گرفته بودند."),
            StoryParagraph("And then, on the very evening they were supposed to leave, the sister, playing her violin to entertain them, drew Gregor out of his room.", "و بعد، در همان شبی که قرار بود بروند، خواهرش که برای سرگرم کردنشان ویولن می‌نواخت، گرگور را از اتاقش بیرون کشید."),
            StoryParagraph("The lodgers, seeing the monstrous creature, were horrified, and they announced that they would leave immediately and would not pay for their stay.", "مستأجرها با دیدن موجود هیولایی وحشت کردند و اعلام کردند که فوراً می‌روند و برای اقامتشان پول نمی‌دهند."),
            StoryParagraph("The father, enraged, attacked Gregor and drove him back into his room, and the sister, in tears, cried out that they must get rid of him.", "پدر خشمگین به گرگور حمله کرد و به اتاقش عقبش راند و خواهرش گریان فریاد کشید که باید از شرش خلاص شوند."),
            StoryParagraph("'We must try to get rid of it,' she said. 'We have to try to take care of ourselves.'", "گفت: «باید تلاش کنیم از شرش خلاص شویم. باید تلاش کنیم از خودمان مراقبت کنیم.»"),
            StoryParagraph("'It is not our brother anymore,' she said. 'It is a creature that must be destroyed.'", "گفت: «دیگر برادرمان نیست. موجودی است که باید نابود شود.»"),
            StoryParagraph("Gregor, lying in his room, heard every word, and he knew, in that moment, that he had lost everything.", "گرگور که در اتاقش دراز کشیده بود، هر کلمه را شنید و در آن لحظه دانست که همه چیز را از دست داده."),
            StoryParagraph("His family had abandoned him completely, and the love they had once felt for him was gone forever.", "خانواده‌اش کاملاً رهایش کرده بودند و عشقی که زمانی برایش حس می‌کردند برای همیشه رفته بود."),
            StoryParagraph("He did not blame them, because he understood, in a way that only the truly abandoned can understand, that they had no choice.", "او سرزنششان نکرد، چون به شکلی که فقط رهاشدگان واقعی می‌فهمند می‌فهمید که آن‌ها انتخاب دیگری نداشتند."),
            StoryParagraph("He had become a burden too heavy to bear, and the only kindness he could offer them was to die.", "او باری بیش از حد سنگین برای تحمل شده بود و تنها مهربانی‌ای که می‌توانست به آن‌ها عرضه کند مردن بود."),
            StoryParagraph("And so, one night, in the silence and darkness, Gregor Samsa made peace with his death, and he closed his eyes, and he waited for the end.", "و اینگونه، یک شب، در سکوت و تاریکی، گرگور سامسا با مرگش صلح کرد و چشمانش را بست و منتظر پایان ماند."),
            StoryParagraph("The end came in the early morning, when his head sank to the floor of its own accord, and his last breath left him without any struggle, without any pain, without any fear.", "پایان در صبح زود آمد، وقتی سرش به‌خودی‌خود روی زمین فرود آمد و آخرین نفسش بدون هیچ تقلا، بدون هیچ درد، بدون هیچ ترسی ترکش کرد.")
        )
    )

    // ─────────── فصل ۵: مرگ گرگور ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Gregor's Death", titlePersian = "مرگ گرگور",
        paragraphs = listOf(
            StoryParagraph("The morning after Gregor's death, the cleaning lady, who came to the apartment early each day, noticed that something was different in the room where the creature lived.", "صبح بعد از مرگ گرگور، زن نظافتچی که هر روز زود به آپارتمان می‌آمد، متوجه شد چیزی در اتاقی که موجود در آن زندگی می‌کرد متفاوت است."),
            StoryParagraph("She opened the door cautiously, as she always did, and she saw the shriveled, lifeless body lying on the floor, dry and flat and utterly motionless.", "او با احتیاط در را باز کرد، همان‌طور که همیشه می‌کرد و جسد خشکیده و بی‌جان را روی زمین دید که خشک و تخت و کاملاً بی‌حرکت بود."),
            StoryParagraph("She poked it with her broom, and when it did not move, she knew that the creature was finally dead, and she let out a long, satisfied whistle.", "با جارویش آن را تکان داد و وقتی حرکت نکرد، دانست که موجود بالاخره مرده است و سوت طولانی و رضایت‌بخشی کشید."),
            StoryParagraph("She went to the family, who were still asleep, and she told them, in a loud, cheerful voice, that the thing in the room had died during the night.", "او به سراغ خانواده رفت که هنوز خواب بودند و با صدای بلند و شادمانه به آن‌ها گفت که آن چیز در اتاق در طول شب مرده است."),
            StoryParagraph("The father sat up in bed, crossed himself, and said, 'Thank God.'", "پدر در تخت نشست، صلیب کشید و گفت: «خدا را شکر.»"),
            StoryParagraph("The mother, who had not slept well for months, looked at her husband with a mixture of relief and guilt, and she too whispered a prayer of thanks.", "مادر که ماه‌ها خوب نخوابیده بود، با آمیزه‌ای از آسودگی و گناه به شوهرش نگاه کرد و او هم دعای تشکری زمزمه کرد."),
            StoryParagraph("The sister, who had been the last to abandon hope, did not say anything; she simply got out of bed, dressed herself, and went to look at the body of her brother.", "خواهر که آخرین کسی بود که امید را رها کرد، چیزی نگفت؛ فقط از تخت بیرون آمد، لباس پوشید و رفت جسد برادرش را ببیند."),
            StoryParagraph("She stood in the doorway for a long moment, looking at the flat, dry shape on the floor, and she felt, at last, that she could feel something again.", "لحظه‌ای طولانی در چارچوب در ایستاد و به شکل تخت و خشک روی زمین نگاه کرد و در نهایت حس کرد می‌تواند دوباره چیزی حس کند."),
            StoryParagraph("But what she felt was not grief, not exactly, and it was not love, not anymore, but a strange, hollow emptiness.", "اما چیزی که حس می‌کرد غم نبود، دقیقاً، و عشق نبود، دیگر نه، بلکه خالی‌بودنی عجیب و توخالی بود."),
            StoryParagraph("It was as though something that had been pressing on her heart for months had finally been removed.", "گویی چیزی که ماه‌ها روی قلبش فشار می‌آورد بالاخره برداشته شده بود."),
            StoryParagraph("She turned away and went to join her parents in the living room, and the three of them sat together for a long time without speaking, each lost in their own thoughts.", "رو برگرداند و به نشیمن رفت تا به والدینش بپیوندد و هر سه مدت طولانی بدون حرف زدن با هم نشستند، هر کدام غرق افکار خودش."),
            StoryParagraph("'We should get rid of it,' the father said finally, breaking the silence. 'It has to be done.'", "پدر بالاخره سکوت را شکست و گفت: «باید از شرش خلاص شویم. باید انجام شود.»"),
            StoryParagraph("The mother nodded, and the sister, after a moment's hesitation, nodded too.", "مادر سر تکان داد و خواهر بعد از لحظه‌ای تردید، او هم سر تکان داد."),
            StoryParagraph("And no one objected, no one suggested a funeral, no one proposed a burial.", "و هیچ‌کس مخالفت نکرد، هیچ‌کس پیشنهاد مراسم خاکسپاری نداد، هیچ‌کس پیشنهاد دفن نکرد."),
            StoryParagraph("Gregor was a creature, not a person, and creatures were not buried; they were disposed of, like garbage, like something that had never really existed.", "گرگور موجودی بود، نه یک شخص و موجودات را دفن نمی‌کردند؛ آن‌ها را دور می‌انداختند، مثل آشغال، مثل چیزی که هرگز واقعاً وجود نداشته."),
            StoryParagraph("The cleaning lady was given the task, and she dragged the body out of the apartment, and she threw it into the trash bin behind the building, and she did not look back.", "وظیفه به زن نظافتچی داده شد و او جسد را از آپارتمان بیرون کشید و در سطل زباله پشت ساختمان انداخت و به عقب نگاه نکرد."),
            StoryParagraph("And so Gregor Samsa, who had once been a human being with a name and a soul and a heart, was reduced to garbage, discarded in the trash, forgotten forever.", "و اینگونه گرگور سامسا، که زمانی انسانی با نام و روح و قلب بود، به زباله تبدیل شد، در سطل آشغال دور انداخته شد، برای همیشه فراموش شد."),
            StoryParagraph("The family, meanwhile, began to plan for their future, a future that no longer included their son and brother.", "خانواده در همین حال، شروع کرد به برنامه‌ریزی برای آینده‌شان، آینده‌ای که دیگر شامل پسر و برادرشان نمی‌شد."),
            StoryParagraph("They decided to move to a smaller apartment, one that they could afford, one that did not contain the room where the creature had lived.", "تصمیم گرفتند به آپارتمانی کوچک‌تر نقل مکان کنند، آپارتمانی که بتوانند بپردازند، آپارتمانی که اتاقی که موجود در آن زندگی کرده بود را نداشته باشد."),
            StoryParagraph("The father, who had recovered some of his old strength, found better work, and he wore his uniform proudly, as though he had finally become a useful member of society again.", "پدر که مقداری از قدرتش را بازیافته بود، کار بهتری پیدا کرد و یونیش را با افتخار می‌پوشید، گویی بالاخره دوباره عضو مفید جامعه شده بود."),
            StoryParagraph("The mother, whose asthma had improved, took in more sewing work, and she began to smile again, for the first time in months.", "مادر که آسمش بهتر شده بود، کار خیاطی بیشتری گرفت و برای اولین بار در ماه‌ها، دوباره شروع کرد به لبخند زدن."),
            StoryParagraph("The sister, who had once dreamed of studying music, had given up that dream, but she had found a new one.", "خواهر که زمانی رؤیای تحصیل موسیقی را داشت، آن رؤیا را رها کرده بود، اما رؤیای جدیدی یافته بود."),
            StoryParagraph("She wanted to work, to earn money, to be independent, to build a life for herself.", "می‌خواست کار کند، پول دربیاورد، مستقل باشد، زندگی‌ای برای خودش بسازد."),
            StoryParagraph("One Sunday, the three of them decided to take a day off from work and to go for a walk in the countryside, away from the city, away from the memories.", "یک یکشنبه، هر سه تصمیم گرفتند از کار مرخصی بگیرند و برای قدم زدن به حومه شهر بروند، دور از شهر، دور از خاطرات."),
            StoryParagraph("The weather was beautiful, the sun was warm, and the trees were in bloom, and as they walked together, they talked about their plans for the future.", "هوا زیبا بود، خورشید گرم بود و درختان شکوفا بودند و همان‌طور که با هم قدم می‌زدند، درباره نقشه‌هایشان برای آینده صحبت کردند."),
            StoryParagraph("The parents looked at their daughter, who had grown into a strong, capable young woman, and they realized, with a mixture of pride and hope, that she was ready to be married.", "والدین به دخترشان نگاه کردند که به زن جوانی قوی و توانمند تبدیل شده بود و با آمیزه‌ای از غرور و امید دریافتند که آماده ازدواج است."),
            StoryParagraph("And as the tram carried them back to the city, back to their new apartment, back to their new life, they felt, for the first time in a long time, that the future was bright, that there was hope again, that happiness was possible.", "و همان‌طور که تراموا آن‌ها را به شهر برگرداند، به آپارتمان جدیدشان، به زندگی جدیدشان، برای اولین بار در مدت طولانی حس کردند که آینده روشن است، دوباره امیدی هست، خوشبختی ممکن است."),
            StoryParagraph("They did not speak of Gregor; they did not mention his name; they did not think, consciously at least, about the son and brother they had lost.", "آن‌ها از گرگور صحبت نکردند؛ نامش را نبردند؛ آگاهانه حداقل، به پسر و برادری که از دست داده بودند فکر نکردند."),
            StoryParagraph("But somewhere, in the deepest part of their hearts, in the place where no words could reach, the memory of him remained.", "اما جایی، در عمیق‌ترین بخش قلبشان، در جایی که هیچ کلمه‌ای نمی‌تواند برسد، خاطره‌اش باقی ماند."),
            StoryParagraph("And it would remain forever, a silent ghost that haunted every moment of happiness.", "و برای همیشه باقی می‌ماند، شبحی خاموش که هر لحظه از خوشبختی را تسخیر می‌کرد."),
            StoryParagraph("For Gregor Samsa had been a human being, had loved and been loved, had sacrificed for his family, had been the best of them in many ways.", "زیرا گرگور سامسا انسانی بوده بود، عشق ورزیده بود و دوستش داشته بودند، برای خانواده‌اش فداکاری کرده بود، از بسیاری جهات بهترینشان بوده بود."),
            StoryParagraph("And yet, when he had needed them most, when he had been at his most vulnerable, they had abandoned him.", "و با این حال، وقتی بیش از هر زمان به آن‌ها نیاز داشت، وقتی در آسیب‌پذیرترین حالتش بود، آن‌ها رهایش کردند."),
            StoryParagraph("Not because they were evil, but because they were human, because they could not bear the weight of a suffering they could not understand.", "نه چون شرور بودند، بلکه چون انسان بودند، چون نمی‌توانستند وزن رنجی که نمی‌فهمیدند را تحمل کنند."),
            StoryParagraph("This was Kafka's vision: that the modern world had made us incapable of love, incapable of compassion, incapable of seeing the humanity in those who are different from us.", "این رؤیای کافکا بود: دنیای مدرن ما را ناتوان از عشق کرده، ناتوان از شفقت، ناتوان از دیدن انسانیت در کسانی که با ما متفاوتند."),
            StoryParagraph("Gregor's transformation was not the tragedy; the tragedy was that, even before he became an insect, he had already been isolated, already been alienated, already been alone.", "دگردیسی گرگور تراژدی نبود؛ تراژدی این بود که حتی قبل از اینکه حشره شود، از قبل منزوی بود، از قبل بیگانه بود، از قبل تنها بود."),
            StoryParagraph("His metamorphosis was merely the physical manifestation of a spiritual transformation that had been taking place in him for years.", "دگردیسی‌اش صرفاً تجلی فیزیکی دگردیسی معنوی‌ای بود که سال‌ها در او رخ می‌داد."),
            StoryParagraph("A slow turning away from humanity, a slow descent into the solitude of the exploited, a slow death of the soul that had preceded the death of the body.", "فاصله‌گیری آهسته از بشریت، نزولی آرام به تنهایی استثمارشدگان، مرگی آهسته روح که پیش از مرگ بدن آمده بود."),
            StoryParagraph("And so his death was not really a death, but a continuation of a process that had begun long before.", "و بنابراین مرگش واقعاً مرگ نبود، بلکه ادامه فرآیندی بود که خیلی قبل‌تر آغاز شده بود."),
            StoryParagraph("A process that the modern world, with its coldness and its cruelty and its endless demands, had made inevitable.", "فرآیندی که دنیای مدرن، با سردی و بی‌رحمی و خواسته‌های بی‌پایانش، اجتناب‌ناپذیر کرده بود.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("The Metamorphosis, published in 1915, is one of the most important works of twentieth-century literature, and one of the most enigmatic.", "مسخ، منتشرشده در ۱۹۱۵، یکی از مهم‌ترین آثار ادبیات قرن بیستم و یکی از معماگونه‌ترین است."),
            StoryParagraph("It is a short novel, barely a hundred pages, but in those pages Kafka created a work of extraordinary depth and power.", "رمانی کوتاه است، به‌سختی صد صفحه، اما در آن صفحات کافکا اثری با عمق و قدرت فوق‌العاده آفرید."),
            StoryParagraph("The plot is simple: a man wakes up one morning to find himself transformed into a giant insect, and he must live out the rest of his life in that form.", "طرح ساده است: مردی یک صبح بیدار می‌شود و خود را به حشره‌ای غول‌آسا تبدیل‌یافته می‌یابد و باید باقی عمرش را در آن شکل بگذراند."),
            StoryParagraph("But the plot is not the point; the plot is merely the situation, and the situation is the vehicle for exploring something much deeper.", "اما طرح نکته اصلی نیست؛ طرح تنها وضعیت است و وضعیت وسیله‌ای است برای کاوش چیزی بسیار عمیق‌تر."),
            StoryParagraph("What Kafka explores, in this brief novel, is the fundamental absurdity of existence, the impossibility of communication, the tragedy of human relationships.", "آنچه کافکا در این رمان کوتاه می‌کاود، پوچی بنیادین وجود است، ناممکن بودن ارتباط، تراژدی روابط انسانی."),
            StoryParagraph("Gregor Samsa is not merely a man who became an insect; he is a symbol of every human being who has ever felt like a stranger in their own life.", "گرگور سامسا تنها مردی نیست که حشره شد؛ نمادی است از هر انسانی که هرگز در زندگی خودش حس کرده غریبه است."),
            StoryParagraph("He is the employee who is valued only for his usefulness; the son who is loved only for what he provides; the brother who is wanted only for his earnings.", "او کارمندی است که تنها به‌خاطر فایده‌اش ارزش‌گذاری می‌شود؛ پسری که تنها به‌خاطر آنچه فراهم می‌کند دوست داشته می‌شود؛ برادری که تنها به‌خاطر درآمدش خواسته می‌شود."),
            StoryParagraph("When he can no longer provide, he is discarded; when he can no longer work, he is abandoned; when he becomes a burden, he is destroyed.", "وقتی دیگر نمی‌تواند فراهم کند، دور انداخته می‌شود؛ وقتی دیگر نمی‌تواند کار کند، رها می‌شود؛ وقتی باری می‌شود، نابود می‌شود."),
            StoryParagraph("This is the tragedy of the modern worker, the modern citizen, the modern human being: that we are valued not for who we are but for what we do.", "این تراژدی کارگر مدرن است، شهروند مدرن، انسان مدرن: ما نه به‌خاطر آنکه هستیم ارزش‌گذاری می‌شویم بلکه به‌خاطر آنچه می‌کنیم."),
            StoryParagraph("The moment we stop being useful, the moment we stop producing, we cease to have value in the eyes of society.", "لحظه‌ای که دیگر مفید نباشیم، لحظه‌ای که تولید را متوقف کنیم، در نظر جامعه ارزشی نداریم."),
            StoryParagraph("And this, Kafka suggests, is not merely an economic truth but a spiritual one; it is a truth about the human soul, not just the human economy.", "و این، کافکا پیشنهاد می‌دهد، تنها حقیقتی اقتصادی نیست بلکه روحی است؛ حقیقتی درباره روح انسانی است، نه فقط اقتصاد انسانی."),
            StoryParagraph("The novel is also, and perhaps most importantly, a study of the family, of the ways in which families both support and destroy their members.", "رمان همچنین، و شاید مهم‌تر، مطالع‌ای است درباره خانواده، درباره شیوه‌هایی که خانواده‌ها اعضایشان را هم حمایت و هم نابود می‌کنند."),
            StoryParagraph("The Samsa family is a family like any other: a father who is weak and resents his weakness; a mother who is sick and resents her sickness.", "خانواده سامسا خانواده‌ای است مثل هر خانواده دیگر: پدری که ضعیف است و از ضعفش کینه دارد؛ مادری که مریض است و از بیماریش کینه دارد."),
            StoryParagraph("A sister who is young and full of dreams, and who must sacrifice her dreams to take care of a brother she can no longer love.", "خواهری که جوان است و پر از رؤیا و باید رؤیاهایش را فدا کند تا از برادری که دیگر نمی‌تواند دوستش بدارد مراقبت کند."),
            StoryParagraph("And at the center of it all, a son who has been the family's provider, and who becomes the family's burden, and who is finally destroyed by the family he has spent his life serving.", "و در مرکز همه‌اش، پسری که نان‌آور خانواده بوده و باری خانواده می‌شود و سرانجام توسط خانواده‌ای که تمام عمرش را صرف خدمت به آن کرده نابود می‌شود."),
            StoryParagraph("The family is not evil; the family is merely human; and the family, like every human institution, is capable of the most terrible cruelty.", "خانواده شرور نیست؛ خانواده تنها انسانی است و خانواده، همچون هر نهاد انسانی، قادر به هولناک‌ترین بی‌رحمی است."),
            StoryParagraph("The novel is also, in a deeper sense, about the impossibility of communication, about the ways in which we are all trapped inside our own minds.", "رمان همچنین، به معنای عمیق‌تر، درباره ناممکن بودن ارتباط است، درباره شیوه‌هایی که همه‌مان درون ذهن خودمان گرفتاریم."),
            StoryParagraph("Gregor can hear everything; he can understand everything; but he cannot speak, and no one can understand what he is trying to say.", "گرگور می‌تواند همه چیز را بشنود؛ می‌تواند همه چیز را بفهمد؛ اما نمی‌تواند صحبت کند و هیچ‌کس نمی‌تواند بفهمد چه می‌خواهد بگوید."),
            StoryParagraph("He is trapped in a body that cannot express his soul; he is trapped in a language that no one else can speak.", "او در بدنی گرفتار است که نمی‌تواند روحش را بیان کند؛ در زبانی گرفتار است که هیچ‌کس دیگری نمی‌تواند صحبتش کند."),
            StoryParagraph("And this, Kafka suggests, is the condition of every human being: that we are all, in our own ways, trapped in bodies and languages that cannot fully express who we are.", "و این، کافکا پیشنهاد می‌دهد، وضعیت هر انسانی است: همه‌مان، به شیوه‌های خودمان، در بدن‌ها و زبان‌هایی گرفتاریم که نمی‌توانند کاملاً آنکه هستیم را بیان کنند."),
            StoryParagraph("The novel is also, and perhaps most deeply, about the nature of transformation, about the ways in which we can become something we never imagined.", "رمان همچنین، و شاید عمیق‌ترین، درباره ماهیت دگردیسی است، درباره شیوه‌هایی که می‌توانیم چیزی شویم که هرگز تصور نمی‌کردیم."),
            StoryParagraph("Gregor wakes up one morning as an insect; we wake up one morning as something else, something we did not choose, something we did not expect.", "گرگور یک صبح به‌عنوان حشره بیدار می‌شود؛ ما یک صبح به‌عنوان چیز دیگری بیدار می‌شویم، چیزی که انتخاب نکردیم، چیزی که انتظارش را نداشتیم."),
            StoryParagraph("We wake up as failures, as strangers, as people who no longer recognize themselves in the mirror.", "به‌عنوان شکست‌خواره بیدار می‌شویم، به‌عنوان غریبه، به‌عنوان افرادی که دیگر خودشان را در آینه نمی‌شناسند."),
            StoryParagraph("We wake up to a life we did not choose, in a world we do not understand, with a self we cannot recognize.", "به زندگی‌ای بیدار می‌شویم که انتخاب نکردیم، در جهانی که نمی‌فهمیم، با خودی که نمی‌توانیم تشخیصش دهیم."),
            StoryParagraph("And the novel asks: what do we do then? How do we live with a self that is not ours?", "و رمان می‌پرسد: آن وقت چه می‌کنیم؟ چطور با خودی زندگی می‌کنیم که مال ما نیست؟"),
            StoryParagraph("Kafka does not answer; Kafka never answers; Kafka only shows us the problem, and leaves us to find our own solution.", "کافکا پاسخ نمی‌دهد؛ کافکا هرگز پاسخ نمی‌دهد؛ کافکا تنها مشکل را نشانمان می‌دهد و می‌گذارد راه‌حل خودمان را بیابیم."),
            StoryParagraph("But the very act of showing us the problem is a kind of answer, because it tells us that we are not alone.", "اما خود عمل نشان دادن مشکل نوعی پاسخ است، چون به ما می‌گوید که تنها نیستیم."),
            StoryParagraph("Others have felt what we feel; others have suffered what we suffer; others have been transformed as we have been transformed.", "دیگران همانی را حس کرده‌اند که ما حس می‌کنیم؛ همانی را کشیده‌اند که ما می‌کشیم؛ همانطور دگردیس شده‌اند که ما دگردیس شده‌ایم."),
            StoryParagraph("And in that shared suffering, in that shared isolation, in that shared humanity, there is a kind of comfort, and a kind of hope.", "و در آن رنج مشترک، در آن انزوای مشترک، در آن انسانیت مشترک، نوعی تسلی هست و نوعی امید."),
            StoryParagraph("The Metamorphosis is not a comforting book; it is not a hopeful book; it is not a book that offers easy answers.", "مسخ کتاب تسلی‌بخشی نیست؛ کتاب امیدبخشی نیست؛ کتابی نیست که پاسخ‌های آسان ارائه دهد."),
            StoryParagraph("But it is a true book, and a great book, and a necessary book, and it will continue to be read as long as there are human beings who feel trapped in their own lives.", "اما کتابی راستین است و کتابی بزرگ و کتابی ضروری و تا وقتی انسان‌هایی باشند که در زندگی خودشان حس گرفتاری کنند خوانده خواهد شد."),
            StoryParagraph("For Gregor Samsa is not merely a character in a novel; he is every person who has ever felt like a stranger, every person who has ever been abandoned, every person who has ever been transformed into something they could not recognize.", "زیرا گرگور سامسا تنها شخصیتی در رمان نیست؛ او هر کسی است که هرگز حس کرده غریبه است، هر کسی که هرگز رها شده، هر کسی که هرگز به چیزی تبدیل شده که نمی‌توانسته تشخیصش دهد."),
            StoryParagraph("He is us, and we are him, and his story is our story, and his death is our death, and his tragedy is our tragedy.", "او ماست و ما اوایم و داستانش داستان ماست و مرگش مرگ ما و تراژدی‌اش تراژدی ما."),
            StoryParagraph("And that, perhaps, is the deepest meaning of the novel: that we are all, in our own ways, Gregor Samsa, waiting to be understood, waiting to be loved, waiting for something that will never come.", "و این، شاید، عمیق‌ترین معنای رمان است: همه‌مان به شیوه‌های خودمان گرگور سامساییم، منتظر فهمیده شدن، منتظر دوست داشته شدن، منتظر چیزی که هرگز نمی‌آید."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of Gregor Samsa is not finished; it is being told every day, in every life that has been touched by isolation, by alienation, by the impossible desire to be understood.", "زیرا داستان گرگور سامسا تمام نشده؛ هر روز گفته می‌شود، در هر زندگی‌ای که توسط انزوا لمس شده، توسط بیگانگی، توسط میل ناممکن به فهمیده شدن."),
            StoryParagraph("And it will continue to be told, as long as there are human beings who feel, as Gregor felt, that they do not belong.", "و به گفتن ادامه می‌یابد، تا وقتی انسان‌هایی باشند که مثل گرگور حس کنند، که تعلق ندارند."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )
}